/**
 * PR #1657 — Screenshot evidence spec
 * Captures admin pages for QA report evidence.
 * Temporary — do not commit.
 */
const { test, expect } = require('@playwright/test');

const BASE = 'http://localhost:8888';
const SS = '/Users/gaelrobin/Local Sites/bwu/app/public/wp-content/plugins/backwpup-pro/.e2e-screenshots';

async function login(page) {
  await page.goto(`${BASE}/wp-login.php`);
  await page.fill('#user_login', 'admin');
  await page.fill('#user_pass', 'password');
  await page.click('#wp-submit');
  await page.waitForURL('**/wp-admin/**');
}

test.describe('PR #1657 — Screenshot Evidence', () => {
  test.beforeEach(async ({ page }) => {
    await login(page);
  });

  test('Smoke-01 — Dashboard loads (no fatal errors)', async ({ page }) => {
    await page.goto(`${BASE}/wp-admin/admin.php?page=backwpup`);
    await page.waitForLoadState('networkidle');
    const content = await page.content();
    expect(content).not.toContain('Fatal error');
    expect(content).not.toContain('Parse error');
    await page.screenshot({ path: `${SS}/pr1657-01-dashboard.png`, fullPage: true });
  });

  test('Smoke-02 — Settings page loads (no fatal errors)', async ({ page }) => {
    await page.goto(`${BASE}/wp-admin/admin.php?page=backwpupsettings`);
    await page.waitForLoadState('networkidle');
    const content = await page.content();
    expect(content).not.toContain('Fatal error');
    expect(content).not.toContain('Parse error');
    await page.screenshot({ path: `${SS}/pr1657-02-settings.png`, fullPage: true });
  });

  test('Smoke-03 — Backups page loads (no fatal errors)', async ({ page }) => {
    await page.goto(`${BASE}/wp-admin/admin.php?page=backwpupbackups`);
    await page.waitForLoadState('networkidle');
    const content = await page.content();
    expect(content).not.toContain('Fatal error');
    expect(content).not.toContain('Parse error');
    await page.screenshot({ path: `${SS}/pr1657-03-backups.png`, fullPage: true });
  });

  test('Smoke-04 — Restore page loads (step=1, no fatal errors)', async ({ page }) => {
    await page.goto(`${BASE}/wp-admin/admin.php?page=backwpuprestore&step=1`);
    await page.waitForLoadState('networkidle');
    const content = await page.content();
    expect(content).not.toContain('Fatal error');
    expect(content).not.toContain('Parse error');
    // Confirm the restore template rendered (bwpr-content div)
    await expect(page.locator('.bwpr-content, [id="bwpr-action-card"]')).toBeVisible({ timeout: 5000 });
    await page.screenshot({ path: `${SS}/pr1657-04-restore-step1.png`, fullPage: true });
  });

  test('AC-link-component — Upgrade link type renders correct CSS class', async ({ page }) => {
    // Navigate to jobs edit page for storage sidebar (if a job exists)
    await page.goto(`${BASE}/wp-admin/admin.php?page=backwpup`);
    await page.waitForLoadState('networkidle');
    await page.screenshot({ path: `${SS}/pr1657-05-jobs-list.png`, fullPage: true });

    // Check if there are any edit job links
    const editLinks = page.locator('a[href*="backwpupeditjob"]');
    const count = await editLinks.count();
    if (count > 0) {
      await editLinks.first().click();
      await page.waitForLoadState('networkidle');
      await page.screenshot({ path: `${SS}/pr1657-06-job-edit.png`, fullPage: true });

      // Look for storage sidebar trigger
      const storageTrigger = page.locator('[data-trigger="open-sidebar"][data-sidebar="storages"], button[data-sidebar="storages"]').first();
      if (await storageTrigger.isVisible().catch(() => false)) {
        await storageTrigger.click();
        await page.waitForTimeout(1000);
        await page.screenshot({ path: `${SS}/pr1657-07-storage-sidebar-open.png`, fullPage: true });
      }
    }
  });

  test('AC-nudge-nonce — nudge_nonce present in JS API object', async ({ page }) => {
    await page.goto(`${BASE}/wp-admin/admin.php?page=backwpup`);
    await page.waitForLoadState('networkidle');
    // Verify nudge_nonce is present in the page's JavaScript
    const content = await page.content();
    expect(content).toContain('nudge_nonce');
    await page.screenshot({ path: `${SS}/pr1657-08-dashboard-nonce-check.png`, fullPage: false });
  });
});
